(54615,0,0,'Over here, $n! Your gyrocopter\'s ready to go!',12,0,100,3,0,0,0,0,0,'Nodd Codejack to Player'),
(72057,0,0,'You will take my place on the eternal brazier.',14,0,100,0,0,38971,0,0,0,'ORDOS - SAY_AGGRO'),
(72057,1,0,'The eternal fire will never be extinguished.',14,0,100,0,0,38972,0,0,0,'ORDOS - SAY_DEATH'),
(72057,2,0,'Up in smoke.',14,0,100,0,0,38977,0,0,0,'ORDOS - SAY_SLAY'),
