(72057,5,0,'You will feel but a fraction of my agony.',14,0,100,0,0,38980,0,0,0,'ORDOS - SAY_POOL_OF_FIRE'),
(72057,6,0,'Burn!',14,0,100,0,0,38981,0,0,0,'ORDOS - SAY_BURNING_SOUL'),
(55135,0,0,'Aim true! Send them limping back to Stormwind!',12,0,100,0,0,32520,0,68804,5,'General Nazgrim'),
(55135,1,0,'Haha! That\'s right. Show them Hellscream\'s fury!',12,0,100,0,0,32516,0,68800,5,'General Nazgrim'),
(63596,0,0,'Interested in catching some rare pets?',12,0,100,1,0,0,0,62763,5,'Audrey Burnhep - Random text'),
(63596,0,1,'You look like someone that might be interested in some rare pets?',12,0,100,1,0,0,0,62764,5,'Audrey Burnhep - Random text'),
(63596,0,2,'Have you ever seen such a beautiful rabbit?  I can help you catch your own!',12,0,100,1,0,0,0,62765,5,'Audrey Burnhep - Random text'),
(63626,0,0,'Interested in catching some rare pets?',12,0,100,1,0,0,0,62763,5,'Varzok - Random text'),
